2️⃣ Праграма-калькулятар з пашыранымі магчымасцямі:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Калькулятар</title>
</head>
<body>
    <h2>Калькулятар</h2>
    <button onclick="calculate()">Вылічыць</button>
    <div id="result" style="margin-top: 20px; font-size: 18px;"></div>

    <script>
        let a = parseFloat(prompt("Увядзі першы лік:"));
        let b = parseFloat(prompt("Увядзі другі лік:"));
        let op = prompt("Увядзі дзеянне (+, -, *, /, ^, %):");

        let result = document.getElementById('result');
        let output;

        if (op === '+') {
            output = a + ' + ' + b + ' = ' + (a + b);
        } else if (op === '-') {
            output = a + ' - ' + b + ' = ' + (a - b);
        } else if (op === '*') {
            output = a + ' * ' + b + ' = ' + (a * b);
        } else if (op === '/') {
            if (b !== 0) {
                output = a + ' / ' + b + ' = ' + (a / b);
            } else {
                output = "❌ Памылка: дзяленне на нуль!";
            }
        } else if (op === '^') {
            output = a + ' ^ ' + b + ' = ' + (a ** b);
        } else if (op === '%') {
            if (b !== 0) {
                output = a + ' % ' + b + ' = ' + (a % b);
            } else {
                output = "❌ Памылка: дзяленне на нуль!";
            }
        } else {
            output = "❌ Невядомае дзеянне!";
        }

        result.innerHTML = output;
    </script>
</body>
</html>
```

3️⃣ Праграма для вызначэння тыпу трохвугольніка:

