    <script>
        let secret = Math.floor(Math.random() * 100) + 1;
        let attempts = 0;
        let guess = 0;
        let output = "";

        while (guess !== secret) {
            guess = parseInt(prompt("Угадай лік (1-100):"));
            attempts = attempts + 1;
            if (guess < secret) {
                output = output + "Спроба " + attempts + ": " + guess + " — Больш!\n";
            } else if (guess > secret) {
                output = output + "Спроба " + attempts + ": " + guess + " — Менш!\n";
            } else {
                output = output + "🎉 Віншую! Ты ўгадаў за " + attempts + " спроб!";
            }
            document.getElementById('result').innerHTML = output;
        }
    </script>
</body>
