Калькулятар, які запамінае папярэдні вынік:

```javascript
let memory = 0;
let result = 0;
let isFirst = true;

while (true) {
    let op = prompt("Увядзі дзеянне (+, -, *, /, c, q):");

    if (op === 'q') {
        console.log("Да пабачэння!");
        break;
    }

    if (op === 'c') {
        memory = 0;
        isFirst = true;
        console.log("Памяць ачышчана");
        continue;
    }

    let num = parseFloat(prompt("Увядзі лік:"));

    if (isFirst) {
        result = num;
        isFirst = false;
    } else {
        if (op === '+') result = result + num;
        else if (op === '-') result = result - num;
        else if (op === '*') result = result * num;
        else if (op === '/') {
            if (num !== 0) result = result / num;
            else console.log("Памылка: дзяленне на нуль!");
        }
    }

    console.log("Вынік:", result);
}
```

