Алгарытм для шыфравання тэксту са зрухам:

```javascript
let text = "ПРЫВІТАННЕ";
let shift = 3;
let encrypted = "";
let decrypted = "";

// Шыфраванне
for (let i = 0; i < text.length; i++) {
    let charCode = text.charCodeAt(i);
    if (charCode >= 1040 && charCode <= 1071) { // А-Я
        charCode = ((charCode - 1040 + shift) % 32) + 1040;
    }
    encrypted = encrypted + String.fromCharCode(charCode);
}
console.log("Зашыфравана:", encrypted);

// Дэшыфраванне
for (let i = 0; i < encrypted.length; i++) {
    let charCode = encrypted.charCodeAt(i);
    if (charCode >= 1040 && charCode <= 1071) {
        charCode = ((charCode - 1040 - shift + 32) % 32) + 1040;
    }
    decrypted = decrypted + String.fromCharCode(charCode);
}
console.log("Расшыфравана:", decrypted);
```

