    <script>
        let numbers = [23, 45, 12, 67, 89, 34, 56, 78, 90, 11, 5, 72, 31, 88, 44];
        let output = "Спіс лікаў: " + numbers.join(", ") + "\n\n";
        let sum = 0;
        let max = numbers[0];
        let min = numbers[0];
        let evenCount = 0;
        let primeCount = 0;

        for (let i = 0; i < numbers.length; i++) {
            sum = sum + numbers[i];
            if (numbers[i] > max) max = numbers[i];
            if (numbers[i] < min) min = numbers[i];
            if (numbers[i] % 2 === 0) evenCount++;

            let isPrime = true;
            if (numbers[i] <= 1) isPrime = false;
            else {
                for (let j = 2; j <= Math.sqrt(numbers[i]); j++) {
                    if (numbers[i] % j === 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
            if (isPrime) primeCount++;
        }

        let average = sum / numbers.length;
        output = output + "Максімальны: " + max + "\n";
        output = output + "Мінімальны: " + min + "\n";
        output = output + "Сума: " + sum + "\n";
        output = output + "Сярэдняе: " + average.toFixed(2) + "\n";
        output = output + "Цотных лікаў: " + evenCount + "\n";
        output = output + "Простых лікаў: " + primeCount;

