            for (let i = 0; i < password.length; i++) {
                let char = password[i];
                if (char >= 'A' && char <= 'Z') hasUpper = true;
                else if (char >= 'a' && char <= 'z') hasLower = true;
                else if (char >= '0' && char <= '9') hasDigit = true;
                else hasSpecial = true;
            }

            let strength = "Слабы";
            if (hasUpper && hasLower && hasDigit) strength = "Сярэдні";
            if (hasUpper && hasLower && hasDigit && hasSpecial) strength = "Надзейны";

            output = output + "Пароль " + (count + 1) + ": " + password + " (" + strength + ")\n";
        }

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

