    <h2>Шыфр Цэзара</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let text = prompt("Увядзі тэкст для шыфравання:");
        let shift = parseInt(prompt("Увядзі зрух (1-32):"));
        let output = "Зыходны тэкст: " + text + "\n";

        // Шыфраванне
        let encrypted = "";
        for (let i = 0; i < text.length; i++) {
            let charCode = text.charCodeAt(i);
            if (charCode >= 1040 && charCode <= 1071) {
                charCode = ((charCode - 1040 + shift) % 32) + 1040;
            } else if (charCode >= 1072 && charCode <= 1103) {
                charCode = ((charCode - 1072 + shift) % 32) + 1072;
            }
            encrypted = encrypted + String.fromCharCode(charCode);
        }
        output = output + "Зашыфравана: " + encrypted + "\n";

        // Дэшыфраванне
        let decrypted = "";
        for (let i = 0; i < encrypted.length; i++) {
            let charCode = encrypted.charCodeAt(i);
            if (charCode >= 1040 && charCode <= 1071) {
                charCode = ((charCode - 1040 - shift + 32) % 32) + 1040;
            } else if (charCode >= 1072 && charCode <= 1103) {
                charCode = ((charCode - 1072 - shift + 32) % 32) + 1072;
            }
            decrypted = decrypted + String.fromCharCode(charCode);
        }
        output = output + "Расшыфравана: " + decrypted;

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
