2️⃣ Гульня «Злаві мяч» з падлікам ачкоў:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Злаві мяч!</title>
</head>
<body>
    <h2>Злаві мяч! (клікні па мячы)</h2>
    <p id="scoreDisplay">Ачкі: 0</p>
    <canvas id="canvas" width="600" height="400"></canvas>
    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        let score = 0;
        let ballX = 200, ballY = 200;
        let radius = 30;
        let dx = 2, dy = 1.5;
        let hue = 0;

        canvas.addEventListener('click', function(e) {
            let rect = canvas.getBoundingClientRect();
            let mouseX = e.clientX - rect.left;
            let mouseY = e.clientY - rect.top;
            let dist = Math.sqrt((mouseX - ballX) ** 2 + (mouseY - ballY) ** 2);
            if (dist < radius) {
                score++;
                document.getElementById('scoreDisplay').innerHTML = 'Ачкі: ' + score;
                radius = Math.max(10, radius - 1);
                dx = dx + 0.1;
                dy = dy + 0.1;
            }
        });

        function animate() {
            ctx.clearRect(0, 0, 600, 400);
            ctx.beginPath();
            ctx.arc(ballX, ballY, radius, 0, Math.PI * 2);
            ctx.fillStyle = 'hsl(' + (score * 15) + ', 100%, 50%)';
            ctx.fill();
            ctx.strokeStyle = 'black';
            ctx.lineWidth = 2;
            ctx.stroke();

            ballX = ballX + dx;
            ballY = ballY + dy;
            if (ballX > 600 - radius || ballX < radius) dx = -dx;
            if (ballY > 400 - radius || ballY < radius) dy = -dy;

            requestAnimationFrame(animate);
        }
        animate();
    </script>
</body>
</html>
```

3️⃣ Калькулятар з гісторыяй:

