    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let history = "";
        let result = 0;
        let isFirst = true;
        let output = "";

        while (true) {
            let op = prompt("Дзеянне (+, -, *, /, h, q):");
            if (op === 'q') {
                output = output + "Да пабачэння!\n";
                break;
            }
            if (op === 'h') {
                output = output + "Гісторыя: " + history + "\n";
                document.getElementById('result').innerHTML = output;
                continue;
            }
            let num = parseFloat(prompt("Увядзі лік:"));
            if (isFirst) {
                result = num;
                isFirst = false;
            } else {
                if (op === '+') result = result + num;
                else if (op === '-') result = result - num;
                else if (op === '*') result = result * num;
                else if (op === '/') {
                    if (num !== 0) result = result / num;
                    else output = output + "Памылка: дзяленне на нуль!\n";
                }
            }
            history = history + result + " ";
            output = output + "Вынік: " + result + "\n";
            document.getElementById('result').innerHTML = output;
        }
        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

