    <script>
        let numbers = [23, 45, 12, 67, 89, 34, 56, 78, 90, 11];
        let output = "Зыходны масіў: " + numbers.join(", ") + "\n\n";

        // Сума
        let sum = 0;
        for (let num of numbers) sum = sum + num;
        output = output + "Сума: " + sum + "\n";

        // Максімум
        let max = numbers[0];
        for (let i = 1; i < numbers.length; i++) {
            if (numbers[i] > max) max = numbers[i];
        }
        output = output + "Максімум: " + max + "\n";

        // Мінімум
        let min = numbers[0];
        for (let i = 1; i < numbers.length; i++) {
            if (numbers[i] < min) min = numbers[i];
        }
        output = output + "Мінімум: " + min + "\n";

        // Сярэдняе
        let avg = sum / numbers.length;
        output = output + "Сярэдняе: " + avg.toFixed(2) + "\n\n";

        // Цотныя лікі
        let even = numbers.filter(num => num % 2 === 0);
        output = output + "Цотныя лікі: " + even.join(", ") + "\n";

        // Лікі > 50
        let greaterThan50 = numbers.filter(num => num > 50);
        output = output + "Лікі > 50: " + greaterThan50.join(", ");

        document.getElementById('result').innerHTML = output;
    </script>
