<body>
    <h2>Табліца множання 10x10</h2>
    <div id="result" style="margin-top: 20px; font-size: 14px; font-family: monospace; white-space: pre-wrap;"></div>
    <script>
        let size = 10;
        let table = [];

        // Запаўненне табліцы
        for (let i = 0; i <= size; i++) {
            table[i] = [];
            for (let j = 0; j <= size; j++) {
                if (i === 0 && j === 0) table[i][j] = "×";
                else if (i === 0) table[i][j] = j;
                else if (j === 0) table[i][j] = i;
                else table[i][j] = i * j;
            }
        }

        // Вывад табліцы
        let output = "";
        for (let i = 0; i <= size; i++) {
            for (let j = 0; j <= size; j++) {
                let val = table[i][j];
                if (val < 10) val = "  " + val;
                else if (val < 100) val = " " + val;
                output = output + val + " ";
            }
            output = output + "\n";
        }
        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
