        // Паэлементныя аперацыі
        let plus5 = numbers.map(x => x + 5);
        let times2 = numbers.map(x => x * 2);
        let squared = numbers.map(x => x ** 2);

        output = output + "+5: " + plus5.join(", ") + "\n";
        output = output + "×2: " + times2.join(", ") + "\n";
        output = output + "Квадраты: " + squared.join(", ") + "\n\n";

        // Фільтрацыя
        let even = numbers.filter(x => x % 2 === 0);
