<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Аперацыі з матрыцамі</title>
</head>
<body>
    <h2>Аперацыі з матрыцамі</h2>
    <div id="result" style="margin-top: 20px; font-size: 16px; font-family: monospace; white-space: pre-wrap;"></div>
    <script>
        let matrixA = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
        let matrixB = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];
        let output = "Матрыца A:\n";
        for (let row of matrixA) {
            output = output + row.join("  ") + "\n";
        }
        output = output + "\nМатрыца B:\n";
        for (let row of matrixB) {
            output = output + row.join("  ") + "\n";
        }

        // Сума матрыц
        let sumMatrix = matrixA.map((row, i) => row.map((val, j) => val + matrixB[i][j]));
        output = output + "\nСума матрыц:\n";
        for (let row of sumMatrix) {
            output = output + row.join("  ") + "\n";
        }

        // Розніца матрыц
        let diffMatrix = matrixA.map((row, i) => row.map((val, j) => val - matrixB[i][j]));
        output = output + "\nРозніца матрыц:\n";
        for (let row of diffMatrix) {
            output = output + row.join("  ") + "\n";
        }

        // Памнажэнне на лік
        let scalarMatrix = matrixA.map(row => row.map(val => val * 2));
        output = output + "\nМатрыца A × 2:\n";
        for (let row of scalarMatrix) {
            output = output + row.join("  ") + "\n";
        }

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

4️⃣ Статыстычны аналіз:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Статыстычны аналіз</title>
</head>
<body>
    <h2>Статыстычны аналіз масіва</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let data = [15, 22, 18, 29, 35, 20, 25, 30, 28, 32, 27, 24, 19, 26, 33];
        let output = "Даныя: " + data.join(", ") + "\n\n";

        // Асноўныя статыстычныя паказчыкі
        let n = data.length;
        let sum = data.reduce((a, b) => a + b, 0);
        let avg = sum / n;
        let sorted = [...data].sort((a, b) => a - b);
        let max = sorted[n-1];
        let min = sorted[0];

        output = output + "Колькасць элементаў: " + n + "\n";
        output = output + "Сума: " + sum + "\n";
        output = output + "Сярэдняе: " + avg.toFixed(2) + "\n";
        output = output + "Максімум: " + max + "\n";
        output = output + "Мінімум: " + min + "\n";
        output = output + "Размах: " + (max - min) + "\n\n";

        // Медыяна
        let median;
        if (n % 2 === 0) {
            median = (sorted[n/2 - 1] + sorted[n/2]) / 2;
        } else {
            median = sorted[Math.floor(n/2)];
        }
        output = output + "Медыяна: " + median + "\n";

        // Дысперсія і стандартнае адхіленне
        let variance = data.reduce((acc, val) => acc + (val - avg) ** 2, 0) / n;
        let stdDev = Math.sqrt(variance);
        output = output + "Дысперсія: " + variance.toFixed(2) + "\n";
        output = output + "Стандартнае адхіленне: " + stdDev.toFixed(2);

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

