theory.content:
Лінейны пошук — гэта паслядоўны перабор усіх элементаў масіва для знаходжання патрэбнага.

📌 **Рэалізацыя лінейнага пошуку:**
```javascript
function linearSearch(arr, target) {
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) {
            return i; // вяртаем індэкс
        }
    }
    return -1; // элемент не знойдзены
}

let numbers = [10, 23, 45, 67, 89, 12, 34];
let index = linearSearch(numbers, 67);
console.log(index); // 3
```

📌 **Пошук усіх уваходжанняў:**
```javascript
function findAllOccurrences(arr, target) {
    let indices = [];
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) {
            indices.push(i);
        }
    }
    return indices;
}

let numbers = [10, 23, 67, 45, 67, 89, 67];
let indices = findAllOccurrences(numbers, 67);
console.log(indices); // [2, 4, 6]
```

📌 **find()** — знаходзіць першы элемент, які задавальняе ўмову:
```javascript
let numbers = [10, 23, 45, 67, 89, 12, 34];

// Знайсці першы цотны лік
let firstEven = numbers.find(num => num % 2 === 0);
console.log(firstEven); // 10

// Знайсці першы лік > 50
let firstGreater50 = numbers.find(num => num > 50);
console.log(firstGreater50); // 67
```

📌 **findIndex()** — знаходзіць індэкс першага элемента, які задавальняе ўмову:
```javascript
// Знайсці індэкс першага цотнага ліка
let index = numbers.findIndex(num => num % 2 === 0);
console.log(index); // 0

// Знайсці індэкс першага ліка > 50
let indexGreater50 = numbers.findIndex(num => num > 50);
console.log(indexGreater50); // 3
```

📌 **find() з аб'ектамі:**
```javascript
let students = [
    {name: "Анна", score: 85},
    {name: "Пётр", score: 92},
    {name: "Марыя", score: 78},
    {name: "Іван", score: 95}
];

// Знайсці студэнта з адзнакай > 90
let topStudent = students.find(s => s.score > 90);
console.log(topStudent); // {name: "Пётр", score: 92}
```

📌 **some()** — правярае, ці ёсць хоць бы адзін элемент, які задавальняе ўмову:
```javascript
let numbers = [10, 23, 45, 67, 89, 12, 34];

// Ці ёсць цотныя лікі?
console.log(numbers.some(num => num % 2 === 0)); // true

// Ці ёсць лікі > 100?
console.log(numbers.some(num => num > 100)); // false
```

📌 **every()** — правярае, ці ўсе элементы задавальняюць ўмову:
```javascript
// Ці ўсе лікі дадатныя?
console.log(numbers.every(num => num > 0)); // true

// Ці ўсе лікі менш за 50?
console.log(numbers.every(num => num < 50)); // false

// Прыклад з аб'ектамі
let students = [
    {name: "Анна", passed: true},
    {name: "Пётр", passed: true},
    {name: "Марыя", passed: false}
];
console.log(students.every(s => s.passed)); // false
```

📌 **Пошук па некалькіх крытэрыях:**
```javascript
let products = [
    {name: "Ноўтбук", price: 1200, category: "электроніка"},
    {name: "Тэлефон", price: 800, category: "электроніка"},
    {name: "Кніга", price: 25, category: "літаратура"},
    {name: "Планшэт", price: 600, category: "электроніка"},
    {name: "Сшытак", price: 3, category: "канцтавары"}
];

// Знайсці першы тавар даражэй за 500 і з катэгорыі "электроніка"
let expensiveElectronic = products.find(p => p.price > 500 && p.category === "электроніка");
console.log(expensiveElectronic); // {name: "Ноўтбук", price: 1200, category: "электроніка"}

// Знайсці ўсе тавары даражэй за 100
let expensive = products.filter(p => p.price > 100);
console.log(expensive); // [Ноўтбук, Тэлефон, Планшэт]

// Праверыць, ці ёсць тавары з катэгорыі "электроніка"
console.log(products.some(p => p.category === "электроніка")); // true
```

practice.description:
Выканайце адно з заданняў на выбар. Капіруйце код у HTML-файл і запусціце ў браўзеры:

1️⃣ Пошук у масіве лікаў:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Пошук у масіве</title>
</head>
<body>
    <h2>Пошук элементаў у масіве</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let numbers = [23, 45, 67, 12, 89, 34, 67, 56, 78, 90, 67];
        let output = "Зыходны масіў: " + numbers.join(", ") + "\n\n";

        // Пошук элемента
        let searchValue = 67;
        let firstIndex = numbers.indexOf(searchValue);
        let lastIndex = numbers.lastIndexOf(searchValue);
        let allIndices = [];
        for (let i = 0; i < numbers.length; i++) {
            if (numbers[i] === searchValue) allIndices.push(i);
        }

        output = output + "Пошук элемента " + searchValue + ":\n";
        output = output + "  Першае ўваходжанне: індэкс " + firstIndex + "\n";
        output = output + "  Апошняе ўваходжанне: індэкс " + lastIndex + "\n";
        output = output + "  Усе ўваходжанні: індэксы " + allIndices.join(", ") + "\n\n";

        // Пошук па ўмове
        let firstEven = numbers.find(num => num % 2 === 0);
        let allEven = numbers.filter(num => num % 2 === 0);
        let firstGreater50 = numbers.find(num => num > 50);
        let allGreater50 = numbers.filter(num => num > 50);
        let hasNegative = numbers.some(num => num < 0);
        let allPositive = numbers.every(num => num > 0);

        output = output + "Пошук па ўмовах:\n";
        output = output + "  Першы цотны лік: " + firstEven + "\n";
        output = output + "  Усе цотныя лікі: " + allEven.join(", ") + "\n";
        output = output + "  Першы лік > 50: " + firstGreater50 + "\n";
        output = output + "  Усе лікі > 50: " + allGreater50.join(", ") + "\n";
        output = output + "  Ці ёсць адмоўныя лікі: " + hasNegative + "\n";
        output = output + "  Ці ўсе лікі дадатныя: " + allPositive;

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

2️⃣ Пошук у масіве аб'ектаў:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Пошук у аб'ектах</title>
</head>
<body>
    <h2>Пошук у масіве аб'ектаў</h2>
    <div id="result" style="margin-top: 20px; font-size: 16px; white-space: pre-wrap;"></div>
    <script>
        let students = [
            {name: "Анна", group: "10А", score: 85},
            {name: "Пётр", group: "10Б", score: 92},
            {name: "Марыя", group: "10А", score: 78},
            {name: "Іван", group: "10Б", score: 95},
            {name: "Алена", group: "10А", score: 88},
            {name: "Аляксей", group: "10В", score: 73}
        ];
        let output = "Спіс студэнтаў:\n";
        for (let s of students) {
            output = output + "  " + s.name + " (" + s.group + ") — " + s.score + " бал.\n";
        }
        output = output + "\n";

        // Пошук па розных крытэрыях
        let topStudent = students.find(s => s.score > 90);
        let allTop = students.filter(s => s.score > 90);
        let groupA = students.filter(s => s.group === "10А");
        let passed = students.filter(s => s.score >= 70);
        let failed = students.filter(s => s.score < 70);
        let highestScore = students.reduce((max, s) => s.score > max.score ? s : max);
        let avgScore = students.reduce((sum, s) => sum + s.score, 0) / students.length;

        output = output + "Вынікі пошуку:\n";
        output = output + "  Першы студэнт з адзнакай > 90: " + topStudent.name + " (" + topStudent.score + ")\n";
        output = output + "  Усе студэнты з адзнакай > 90: " + allTop.map(s => s.name).join(", ") + "\n";
        output = output + "  Студэнты групы 10А: " + groupA.map(s => s.name).join(", ") + "\n";
        output = output + "  Студэнты, якія здалі (>=70): " + passed.map(s => s.name).join(", ") + "\n";
        output = output + "  Студэнты, якія не здалі (<70): " + failed.map(s => s.name).join(", ") + "\n";
        output = output + "  Найвышэйшая адзнака: " + highestScore.name + " — " + highestScore.score + "\n";
        output = output + "  Сярэдняя адзнака: " + avgScore.toFixed(2);

        document.getElementById('result').innerHTML = output;
    </script>
