Выканайце адно з заданняў на выбар. Капіруйце код у HTML-файл і запусціце ў браўзеры:

1️⃣ Бінарны пошук:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Бінарны пошук</title>
</head>
<body>
    <h2>Бінарны пошук у адсартаваным масіве</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let numbers = [10, 23, 34, 45, 56, 67, 78, 89, 90, 100, 123, 145];
        let output = "Масіў: " + numbers.join(", ") + "\n\n";

        function binarySearch(arr, target) {
            let left = 0;
            let right = arr.length - 1;
            let steps = 0;

            while (left <= right) {
                steps++;
                let mid = Math.floor((left + right) / 2);
                output = output + "Крок " + steps + ": mid=" + mid + ", arr[" + mid + "]=" + arr[mid] + "\n";

                if (arr[mid] === target) {
                    return {index: mid, steps: steps};
                } else if (arr[mid] < target) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            return {index: -1, steps: steps};
        }

        let searchValue = 67;
        output = output + "Пошук элемента " + searchValue + ":\n";
        let result = binarySearch(numbers, searchValue);

        if (result.index !== -1) {
            output = output + "\n✅ Элемент знойдзены на індэксе " + result.index;
        } else {
            output = output + "\n❌ Элемент не знойдзены";
        }
        output = output + "\nКолькасць крокаў: " + result.steps;

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

2️⃣ Пошук з рэгулярнымі выразамі:

