theory.content:
📌 **Пошук максімальнага элемента ў масіве — адна з самых частых задач у праграмаванні.**

📌 **Алгарытм пошуку максімуму:**
1. Прыняць першы элемент за максімальны
2. Параўнаць яго з усімі наступнымі элементамі
3. Калі які-небудзь элемент больш — запомніць яго
4. Вярнуць знойдзены максімум

📌 **Рэалізацыя на JavaScript:**
```javascript
function findMax(arr) {
    let max = arr[0];
    for (let i = 1; i < arr.length; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

let numbers = [12, 45, 7, 89, 23, 56, 34, 78];
console.log("Максімум:", findMax(numbers)); // 89
```

📌 **З выкарыстаннем Math.max() і spread-аператара:**
```javascript
let max = Math.max(...numbers);
console.log("Максімум:", max); // 89
```

📌 **З выкарыстаннем reduce():**
```javascript
let max = numbers.reduce((a, b) => a > b ? a : b);
console.log("Максімум:", max); // 89
```

📌 **Пошук мінімальнага элемента — аналагічны алгарытм, але з умовай «менш».**

📌 **Рэалізацыя на JavaScript:**
```javascript
function findMin(arr) {
    let min = arr[0];
    for (let i = 1; i < arr.length; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

let numbers = [12, 45, 7, 89, 23, 56, 34, 78];
console.log("Мінімум:", findMin(numbers)); // 7
```

📌 **З выкарыстаннем Math.min() і spread-аператара:**
```javascript
let min = Math.min(...numbers);
console.log("Мінімум:", min); // 7
```

📌 **З выкарыстаннем reduce():**
```javascript
let min = numbers.reduce((a, b) => a < b ? a : b);
console.log("Мінімум:", min); // 7
```

📌 **Часта патрэбна знайсці адначасова і максімум, і мінімум.**

📌 **Эфектыўны алгарытм:**
```javascript
function findMinMax(arr) {
    let min = arr[0];
    let max = arr[0];
    for (let i = 1; i < arr.length; i++) {
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
    }
    return {min: min, max: max};
}

let numbers = [12, 45, 7, 89, 23, 56, 34, 78];
let result = findMinMax(numbers);
console.log("Мінімум:", result.min, "Максімум:", result.max);
```

📌 **З выкарыстаннем Math.max() і Math.min():**
```javascript
let max = Math.max(...numbers);
let min = Math.min(...numbers);
console.log("Мінімум:", min, "Максімум:", max);
```

📌 **Часта трэба знайсці аб'ект з максімальным/мінімальным значэннем пэўнага поля.**

📌 **Пошук аб'екта з максімальнай адзнакай:**
```javascript
let students = [
    {name: "Анна", score: 85},
    {name: "Пётр", score: 92},
    {name: "Марыя", score: 78},
    {name: "Іван", score: 95},
    {name: "Алена", score: 88}
];

// Пошук аб'екта з максімальнай адзнакай
let topStudent = students.reduce((best, current) => 
    current.score > best.score ? current : best
);
console.log("Лепшы студэнт:", topStudent.name, topStudent.score);

// Пошук аб'екта з мінімальнай адзнакай
let worstStudent = students.reduce((worst, current) => 
    current.score < worst.score ? current : worst
);
console.log("Горшы студэнт:", worstStudent.name, worstStudent.score);
```

📌 **З выкарыстаннем find() і Math.max():**
```javascript
let maxScore = Math.max(...students.map(s => s.score));
let topStudent = students.find(s => s.score === maxScore);
console.log("Лепшы студэнт:", topStudent.name, topStudent.score);
```

📌 **Часта патрэбна знайсці не адзін, а некалькі максімальных або мінімальных элементаў.**

📌 **Пошук усіх максімальных элементаў:**
```javascript
function findAllMax(arr) {
    let max = Math.max(...arr);
    let indices = [];
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === max) {
            indices.push(i);
        }
    }
    return {value: max, indices: indices};
}

let numbers = [12, 89, 45, 7, 89, 23, 56, 89, 34, 78];
let result = findAllMax(numbers);
console.log("Максімальнае значэнне:", result.value);
console.log("Індэксы:", result.indices); // [1, 4, 7]
```

📌 **Пошук N найбольшых элементаў:**
```javascript
function findTopN(arr, n) {
    let sorted = [...arr].sort((a, b) => b - a);
    return sorted.slice(0, n);
}

let numbers = [12, 45, 7, 89, 23, 56, 34, 78];
let top3 = findTopN(numbers, 3);
console.log("Тры найбольшыя:", top3); // [89, 78, 56]
```

📌 **Пошук N найменшых элементаў:**
```javascript
function findBottomN(arr, n) {
    let sorted = [...arr].sort((a, b) => a - b);
    return sorted.slice(0, n);
}

let bottom3 = findBottomN(numbers, 3);
console.log("Тры найменшыя:", bottom3); // [7, 12, 23]
```

📌 **Задача 1: Дыяпазон (размах) даных**
```javascript
let data = [15, 22, 18, 29, 35, 20, 25, 30, 28, 32];
let max = Math.max(...data);
let min = Math.min(...data);
let range = max - min;
console.log("Дыяпазон:", range); // 20
```

📌 **Задача 2: Нармалізацыя даных**
```javascript
let data = [10, 20, 30, 40, 50];
let max = Math.max(...data);
let min = Math.min(...data);
let normalized = data.map(x => (x - min) / (max - min));
console.log("Нармалізаваныя даныя:", normalized); // [0, 0.25, 0.5, 0.75, 1]
```

📌 **Задача 3: Выкіды (выяўленне анамалій)**
```javascript
let data = [10, 12, 11, 13, 14, 12, 100, 11, 13, 12];
let max = Math.max(...data);
let min = Math.min(...data);
let avg = data.reduce((a, b) => a + b, 0) / data.length;
let threshold = 3;

let outliers = data.filter(x => Math.abs(x - avg) > threshold * 2);
console.log("Анамальныя значэнні:", outliers); // [100]
```

📌 **Задача 4: Пошук найбольш аддаленых элементаў**
```javascript
let data = [10, 20, 30, 40, 50];
let avg = data.reduce((a, b) => a + b, 0) / data.length;
let maxDist = data.reduce((max, x) => Math.abs(x - avg) > Math.abs(max - avg) ? x : max);
console.log("Элемент, найбольш аддалены ад сярэдняга:", maxDist);
```

