        for (let i = 1; i < numbers.length; i++) {
            if (numbers[i] > max) {
                max = numbers[i];
                maxIndex = i;
            }
            if (numbers[i] < min) {
                min = numbers[i];
                minIndex = i;
            }
        }

        output = output + "Максімальны элемент: " + max + " (індэкс " + maxIndex + ")\n";
        output = output + "Мінімальны элемент: " + min + " (індэкс " + minIndex + ")\n";
        output = output + "Дыяпазон (размах): " + (max - min) + "\n";

        // Усе ўваходжанні максімуму
        let allMaxIndices = [];
        for (let i = 0; i < numbers.length; i++) {
            if (numbers[i] === max) allMaxIndices.push(i);
        }
        output = output + "Усе ўваходжанні максімуму: індэксы " + allMaxIndices.join(", ") + "\n";

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

