    <script>
        let data = [10, 12, 11, 13, 14, 12, 11, 13, 12, 100, 11, 13, 14, 12, 11, 13, 12, 11, 13, 12];
        let output = "Даныя: " + data.join(", ") + "\n\n";

        let max = Math.max(...data);
        let min = Math.min(...data);
        let sum = data.reduce((a, b) => a + b, 0);
        let avg = sum / data.length;
        let maxDeviation = Math.max(...data.map(x => Math.abs(x - avg)));

        output = output + "Сярэдняе: " + avg.toFixed(2) + "\n";
        output = output + "Максімальнае адхіленне ад сярэдняга: " + maxDeviation.toFixed(2) + "\n\n";

        // Выяўленне анамалій (значэнні, якія адрозніваюцца больш чым на 2*стандартнае адхіленне)
        let variance = data.reduce((a, x) => a + (x - avg) ** 2, 0) / data.length;
        let stdDev = Math.sqrt(variance);
        let threshold = stdDev * 2;

        output = output + "Стандартнае адхіленне: " + stdDev.toFixed(2) + "\n";
        output = output + "Парог (2*σ): " + threshold.toFixed(2) + "\n\n";

        let outliers = data.filter(x => Math.abs(x - avg) > threshold);
        output = output + "Анамальныя значэнні: " + (outliers.length > 0 ? outliers.join(", ") : "не знойдзены") + "\n";

