```javascript
let students = [
    {id: 1, name: "Анна", group: "10А", score: 85},
    {id: 2, name: "Пётр", group: "10Б", score: 92},
    {id: 3, name: "Марыя", group: "10А", score: 78},
    {id: 4, name: "Іван", group: "10Б", score: 95},
    {id: 5, name: "Алена", group: "10А", score: 88}
];

// Функцыі для працы са студэнтамі
function addStudent(name, group, score) {
    let id = students.length > 0 ? Math.max(...students.map(s => s.id)) + 1 : 1;
    students.push({id, name, group, score});
}

function removeStudent(id) {
    students = students.filter(s => s.id !== id);
}

function findTopStudents(n) {
    return [...students].sort((a, b) => b.score - a.score).slice(0, n);
}

function getGroupAverage(group) {
    let groupStudents = students.filter(s => s.group === group);
    if (groupStudents.length === 0) return 0;
    let sum = groupStudents.reduce((acc, s) => acc + s.score, 0);
    return sum / groupStudents.length;
}

function updateStudent(id, newScore) {
    let student = students.find(s => s.id === id);
    if (student) student.score = newScore;
}

function getGroupStats() {
    let groups = {};
    for (let s of students) {
        if (!groups[s.group]) groups[s.group] = [];
        groups[s.group].push(s);
    }
    let stats = {};
    for (let group in groups) {
        let scores = groups[group].map(s => s.score);
        stats[group] = {
            count: scores.length,
            avg: scores.reduce((a, b) => a + b, 0) / scores.length,
            max: Math.max(...scores),
            min: Math.min(...scores)
        };
    }
    return stats;
}

// Прыклад выкарыстання
console.log("Усе студэнты:", students);
console.log("Лепшыя 3 студэнты:", findTopStudents(3));
console.log("Сярэдні бал у 10А:", getGroupAverage("10А"));
console.log("Статыстыка па групах:", getGroupStats());
```

