    <script>
        let students = [
            {id: 1, name: "Анна", group: "10А", score: 85},
            {id: 2, name: "Пётр", group: "10Б", score: 92},
            {id: 3, name: "Марыя", group: "10А", score: 78},
            {id: 4, name: "Іван", group: "10Б", score: 95},
            {id: 5, name: "Алена", group: "10А", score: 88},
            {id: 6, name: "Аляксей", group: "10В", score: 73},
            {id: 7, name: "Наталля", group: "10Б", score: 81},
            {id: 8, name: "Дзмітрый", group: "10В", score: 67},
            {id: 9, name: "Вольга", group: "10А", score: 91},
            {id: 10, name: "Міхаіл", group: "10В", score: 79}
        ];
        let output = "🏫 Усе студэнты: " + students.length + " чалавек\n\n";

        // Спіс студэнтаў
        output = output + "📋 Поўны спіс:\n";
        for (let s of students) {
            output = output + "  " + s.id + ". " + s.name + " (" + s.group + ") — " + s.score + " бал.\n";
        }
        output = output + "\n";

        // Статыстыка па групах
        output = output + "📊 Статыстыка па групах:\n";
        let groups = {};
        for (let s of students) {
            if (!groups[s.group]) groups[s.group] = [];
            groups[s.group].push(s);
        }
        for (let group in groups) {
            let scores = groups[group].map(s => s.score);
            let avg = scores.reduce((a, b) => a + b, 0) / scores.length;
            let max = Math.max(...scores);
            let min = Math.min(...scores);
            let top = groups[group].reduce((a, b) => a.score > b.score ? a : b);
            output = output + "  " + group + ":\n";
            output = output + "    Колькасць: " + groups[group].length + "\n";
            output = output + "    Сярэдні бал: " + avg.toFixed(2) + "\n";
            output = output + "    Максімум: " + max + " (" + top.name + ")\n";
            output = output + "    Мінімум: " + min + "\n";
        }
        output = output + "\n";

        // Топ студэнтаў
        let sorted = [...students].sort((a, b) => b.score - a.score);
        output = output + "🏆 Топ-5 студэнтаў:\n";
        for (let i = 0; i < Math.min(5, sorted.length); i++) {
            output = output + "  " + (i+1) + ". " + sorted[i].name + " (" + sorted[i].group + ") — " + sorted[i].score + " бал.\n";
        }

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

2️⃣ Аналізатар тэксту:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Аналізатар тэксту</title>
</head>
<body>
    <h2>Аналізатар тэксту</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let text = "JavaScript — гэта мова праграмавання, якая дазваляе ствараць інтэрактыўныя вэб-старонкі. Мова JavaScript была створана ў 1995 годзе. Сёння JavaScript з'яўляецца адной з самых папулярных моў праграмавання ў свеце.";
        let output = "📝 Тэкст для аналізу:\n" + text + "\n\n";

        // Разбіваю на словы
        let words = text.split(/[\s,.!?—]+/).filter(w => w.length > 0);
        output = output + "📊 Статыстыка:\n";
        output = output + "  Колькасць слоў: " + words.length + "\n";
        output = output + "  Колькасць сімвалаў: " + text.length + "\n";

        // Даўжыня слоў
        let lengths = words.map(w => w.length);
        let avgLength = lengths.reduce((a, b) => a + b, 0) / lengths.length;
        let maxLength = Math.max(...lengths);
        let minLength = Math.min(...lengths);
        output = output + "  Сярэдняя даўжыня слова: " + avgLength.toFixed(2) + "\n";
        output = output + "  Максімальная даўжыня слова: " + maxLength + "\n";
        output = output + "  Мінімальная даўжыня слова: " + minLength + "\n\n";

        // Частата слоў
        let freq = {};
        for (let w of words) {
            let key = w.toLowerCase();
            freq[key] = (freq[key] || 0) + 1;
        }
        let sortedWords = Object.entries(freq).sort((a, b) => b[1] - a[1]);
        output = output + "🔢 Частата слоў (топ-5):\n";
        for (let i = 0; i < Math.min(5, sortedWords.length); i++) {
            output = output + "  " + sortedWords[i][0] + " — " + sortedWords[i][1] + " раз(ы)\n";
        }

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

3️⃣ Канвертар масіваў:

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Канвертар масіваў</title>
</head>
<body>
    <h2>Канвертар масіваў</h2>
    <div id="result" style="margin-top: 20px; font-size: 18px; white-space: pre-wrap;"></div>
    <script>
        let numbers = [5, 12, 8, 23, 17, 9, 31, 14, 6, 25];
        let output = "Зыходны масіў: " + numbers.join(", ") + "\n\n";

        // Усе аперацыі з масівам
        output = output + "📊 Розныя пераўтварэнні:\n\n";

        // map
        let doubled = numbers.map(x => x * 2);
        output = output + "×2: " + doubled.join(", ") + "\n";

        // filter
        let even = numbers.filter(x => x % 2 === 0);
        output = output + "Цотныя: " + even.join(", ") + "\n";

        // sort
        let sorted = [...numbers].sort((a, b) => a - b);
        output = output + "Сартыраваны: " + sorted.join(", ") + "\n";

        // reverse
        let reversed = [...numbers].reverse();
        output = output + "Рэверс: " + reversed.join(", ") + "\n";

        // reduce
        let sum = numbers.reduce((a, b) => a + b, 0);
        let avg = sum / numbers.length;
        let max = Math.max(...numbers);
        let min = Math.min(...numbers);
        output = output + "\n📈 Статыстыка:\n";
        output = output + "  Сума: " + sum + "\n";
        output = output + "  Сярэдняе: " + avg.toFixed(2) + "\n";
        output = output + "  Максімум: " + max + "\n";
        output = output + "  Мінімум: " + min + "\n";
        output = output + "  Дыяпазон: " + (max - min) + "\n";

        document.getElementById('result').innerHTML = output;
    </script>
</body>
</html>
```

