📌 **«Інтэрактыўны светлафор»**

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Светлафор</title>
    <style>
        .traffic-light { width: 120px; padding: 20px; background: #333; border-radius: 20px; margin: 20px auto; }
        .light { width: 80px; height: 80px; border-radius: 50%; margin: 10px auto; background: #444; }
        button { padding: 10px 20px; margin: 5px; cursor: pointer; }
        .info { text-align: center; font-size: 20px; }
    </style>
</head>
<body>
    <h1 style="text-align:center;">🚦 Светлафор</h1>
    <div class="traffic-light">
        <div class="light" id="red"></div>
        <div class="light" id="yellow"></div>
        <div class="light" id="green"></div>
    </div>
    <div style="text-align:center;">
        <button id="nextBtn">Наступны сігнал</button>
        <button id="autoBtn">Аўтаматычны рэжым</button>
    </div>
    <div class="info" id="signal">Бягучы сігнал: Чырвоны</div>

    <script>
        const red = document.getElementById('red');
        const yellow = document.getElementById('yellow');
        const green = document.getElementById('green');
        const signal = document.getElementById('signal');
        const nextBtn = document.getElementById('nextBtn');
        const autoBtn = document.getElementById('autoBtn');

        let state = 0;
        let autoInterval = null;
        const states = [
            { red: 'red', yellow: '#444', green: '#444', text: 'Стой! Чырвоны' },
            { red: '#444', yellow: '#f1c40f', green: '#444', text: 'Увага! Жоўты' },
            { red: '#444', yellow: '#444', green: '#2ecc71', text: 'Ідзі! Зялёны' }
        ];

        function updateLight() {
            const s = states[state];
            red.style.backgroundColor = s.red;
            yellow.style.backgroundColor = s.yellow;
            green.style.backgroundColor = s.green;
            signal.textContent = 'Бягучы сігнал: ' + s.text;
        }

        nextBtn.addEventListener('click', function() {
            state = (state + 1) % states.length;
            updateLight();
        });

        autoBtn.addEventListener('click', function() {
            if (autoInterval) {
                clearInterval(autoInterval);
                autoInterval = null;
                autoBtn.textContent = 'Аўтаматычны рэжым';
            } else {
                autoInterval = setInterval(function() {
                    state = (state + 1) % states.length;
                    updateLight();
                }, 1500);
                autoBtn.textContent = 'Спыніць аўтамат';
            }
        });

        updateLight();
    </script>
</body>
</html>
```

