```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Укладкі</title>
    <style>
        .tabs { display: flex; gap: 5px; }
        .tab { padding: 10px 20px; cursor: pointer; background: #ecf0f1; border-radius: 8px 8px 0 0; }
        .tab.active { background: #3498db; color: white; }
        .content { border: 1px solid #ddd; padding: 20px; border-radius: 0 0 8px 8px; }
        .page { display: none; }
        .page.active { display: block; }
    </style>
</head>
<body>
    <div class="tabs">
        <div class="tab active" data-tab="1">Галоўная</div>
        <div class="tab" data-tab="2">Налады</div>
        <div class="tab" data-tab="3">Прафайл</div>
    </div>
    <div class="content">
        <div class="page active" id="page1">Галоўная старонка</div>
        <div class="page" id="page2">Старонка налад</div>
        <div class="page" id="page3">Старонка прафайла</div>
    </div>
    <script>
        document.querySelectorAll('.tab').forEach(tab => {
            tab.addEventListener('click', function() {
                document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
                this.classList.add('active');
                document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
                document.getElementById('page' + this.dataset.tab).classList.add('active');
            });
        });
    </script>
</body>
</html>
