📌 **Поўная форма рэгістрацыі з праверкай:**

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Рэгістрацыя</title>
    <style>
        body { font-family: Arial; background: #f0f4f8; display: flex; justify-content: center; align-items: center; height: 100vh; margin: 0; }
        .form-container {
            background: white;
            padding: 30px;
            border-radius: 16px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.2);
            width: 400px;
        }
        .form-group { margin-bottom: 15px; }
        .form-group label { display: block; margin-bottom: 5px; font-weight: bold; }
        .form-group input, .form-group select { width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 8px; box-sizing: border-box; }
        .form-group input:focus { border-color: #3498db; outline: none; }
        .btn { width: 100%; padding: 12px; border: none; border-radius: 8px; background: #3498db; color: white; font-size: 16px; cursor: pointer; transition: 0.3s; }
        .btn:hover { background: #2980b9; }
        .btn:disabled { opacity: 0.5; cursor: not-allowed; }
        .error { color: #e74c3c; font-size: 14px; margin-top: 5px; display: none; }
        .success { color: #2ecc71; font-size: 16px; text-align: center; margin-top: 15px; display: none; }
        .checkbox-group { display: flex; align-items: center; gap: 10px; }
        .checkbox-group input { width: auto; }
    </style>
</head>
<body>
    <div class="form-container">
        <h2>📝 Рэгістрацыя</h2>
        <form id="registerForm">
            <div class="form-group">
                <label for="name">Поўнае імя</label>
                <input type="text" id="name" placeholder="Увядзі імя..." required>
                <div class="error" id="nameError">Калі ласка, увядзіце імя (не менш за 2 сімвалы)</div>
            </div>
            <div class="form-group">
                <label for="email">Email</label>
                <input type="email" id="email" placeholder="Увядзі email..." required>
                <div class="error" id="emailError">Калі ласка, увядзіце карэктны email</div>
            </div>
            <div class="form-group">
                <label for="password">Пароль</label>
                <input type="password" id="password" placeholder="Увядзі пароль..." required>
                <div class="error" id="passwordError">Пароль павінен утрымліваць не менш за 6 сімвалаў</div>
            </div>
            <div class="form-group">
                <label for="role">Роля</label>
                <select id="role">
                    <option value="student">Студэнт</option>
                    <option value="teacher">Настаўнік</option>
                    <option value="admin">Адміністратар</option>
                </select>
            </div>
            <div class="form-group checkbox-group">
                <input type="checkbox" id="agree">
                <label for="agree">Я згодны з умовамі выкарыстання</label>
            </div>
            <button type="submit" class="btn" id="submitBtn" disabled>Зарэгістравацца</button>
            <div class="success" id="successMessage">✅ Рэгістрацыя паспяхова завершана!</div>
        </form>
    </div>

    <script>
        const nameInput = document.getElementById('name');
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const roleSelect = document.getElementById('role');
        const agreeCheck = document.getElementById('agree');
        const submitBtn = document.getElementById('submitBtn');
        const successMsg = document.getElementById('successMessage');
        const nameError = document.getElementById('nameError');
        const emailError = document.getElementById('emailError');
        const passwordError = document.getElementById('passwordError');

        function validateForm() {
            let valid = true;

            // Імя
            if (nameInput.value.length < 2) {
                nameError.style.display = 'block';
                valid = false;
            } else {
                nameError.style.display = 'none';
            }

            // Email
            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(emailInput.value)) {
                emailError.style.display = 'block';
                valid = false;
            } else {
                emailError.style.display = 'none';
            }

            // Пароль
            if (passwordInput.value.length < 6) {
                passwordError.style.display = 'block';
                valid = false;
            } else {
                passwordError.style.display = 'none';
            }

            // Згода
            if (!agreeCheck.checked) {
                valid = false;
            }

            submitBtn.disabled = !valid;
            return valid;
        }

        [nameInput, emailInput, passwordInput, agreeCheck].forEach(el => {
            el.addEventListener('input', validateForm);
            el.addEventListener('change', validateForm);
        });

        document.getElementById('registerForm').addEventListener('submit', function(e) {
            e.preventDefault();
            if (validateForm()) {
                successMsg.style.display = 'block';
                submitBtn.disabled = true;
                setTimeout(() => {
                    successMsg.style.display = 'none';
                    submitBtn.disabled = false;
                    this.reset();
                    validateForm();
                }, 3000);
            }
        });

        validateForm();
    </script>
</body>
</html>
```

