📌 **Просты графічны рэдактар з элементамі кіравання:**

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Графічны рэдактар</title>
    <style>
        body { font-family: Arial; background: #f0f4f8; padding: 20px; }
        .container { max-width: 800px; margin: 0 auto; background: white; padding: 20px; border-radius: 16px; box-shadow: 0 4px 20px rgba(0,0,0,0.1); }
        .toolbar { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 15px; align-items: center; }
        .toolbar label { font-weight: bold; font-size: 14px; }
        .toolbar input[type="color"] { width: 40px; height: 40px; border: none; cursor: pointer; }
        .toolbar input[type="range"] { width: 100px; }
        .toolbar button { padding: 8px 16px; border: none; border-radius: 6px; cursor: pointer; background: #3498db; color: white; }
        .toolbar button:hover { background: #2980b9; }
        .toolbar button.danger { background: #e74c3c; }
        .toolbar button.danger:hover { background: #c0392b; }
        canvas { border: 2px solid #ddd; border-radius: 8px; display: block; }
        .info { margin-top: 10px; font-size: 14px; color: #666; }
    </style>
</head>
<body>
    <div class="container">
        <h1>🎨 Графічны рэдактар</h1>
        <div class="toolbar">
            <label>Колер:</label>
            <input type="color" id="colorPicker" value="#3498db">
            <label>Таўшчыня:</label>
            <input type="range" id="lineWidth" min="1" max="20" value="3">
            <span id="sizeDisplay">3</span>
            <button id="clearBtn" class="danger">Ачысціць</button>
            <button id="undoBtn">Назад</button>
        </div>
        <canvas id="canvas" width="700" height="400"></canvas>
        <div class="info">🖱️ Малюйце, перацягваючы мыш. Выкарыстоўвайце элементы кіравання для наладкі.</div>
    </div>

    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const colorPicker = document.getElementById('colorPicker');
        const lineWidth = document.getElementById('lineWidth');
        const sizeDisplay = document.getElementById('sizeDisplay');
        const clearBtn = document.getElementById('clearBtn');
        const undoBtn = document.getElementById('undoBtn');

        let isDrawing = false;
        let lastX = 0, lastY = 0;
        let history = [];
        let currentState = 0;

        function saveState() {
            history = history.slice(0, currentState + 1);
            history.push(canvas.toDataURL());
            currentState = history.length - 1;
        }

        function restoreState(index) {
            if (index < 0 || index >= history.length) return;
            const img = new Image();
            img.src = history[index];
            img.onload = function() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                currentState = index;
            };
        }

        function getPosition(e) {
            const rect = canvas.getBoundingClientRect();
            return {
                x: (e.clientX || e.touches[0].clientX) - rect.left,
                y: (e.clientY || e.touches[0].clientY) - rect.top
            };
        }

        function startDrawing(e) {
            e.preventDefault();
            isDrawing = true;
            const pos = getPosition(e);
            lastX = pos.x;
            lastY = pos.y;
        }

        function draw(e) {
            e.preventDefault();
            if (!isDrawing) return;
            const pos = getPosition(e);
            ctx.beginPath();
            ctx.moveTo(lastX, lastY);
            ctx.lineTo(pos.x, pos.y);
            ctx.strokeStyle = colorPicker.value;
            ctx.lineWidth = lineWidth.value;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.stroke();
            lastX = pos.x;
            lastY = pos.y;
        }

        function stopDrawing(e) {
            if (isDrawing) {
                isDrawing = false;
                saveState();
            }
        }

        canvas.addEventListener('mousedown', startDrawing);
        canvas.addEventListener('mousemove', draw);
        canvas.addEventListener('mouseup', stopDrawing);
        canvas.addEventListener('mouseleave', stopDrawing);

        canvas.addEventListener('touchstart', startDrawing);
        canvas.addEventListener('touchmove', draw);
        canvas.addEventListener('touchend', stopDrawing);

        lineWidth.addEventListener('input', function() {
            sizeDisplay.textContent = this.value;
        });

        clearBtn.addEventListener('click', function() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            saveState();
        });

        undoBtn.addEventListener('click', function() {
            if (currentState > 0) {
                restoreState(currentState - 1);
            }
        });

        saveState();
    </script>
</body>
</html>
```

📌 **Слупковая дыяграма з элементамі кіравання:**

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Слупковая дыяграма</title>
    <style>
        body { font-family: Arial; background: #f0f4f8; padding: 20px; }
        .container { max-width: 800px; margin: 0 auto; background: white; padding: 20px; border-radius: 16px; box-shadow: 0 4px 20px rgba(0,0,0,0.1); }
        .controls { display: flex; gap: 15px; margin-bottom: 15px; flex-wrap: wrap; align-items: center; }
        .controls button { padding: 8px 16px; border: none; border-radius: 6px; cursor: pointer; background: #3498db; color: white; }
        .controls button:hover { background: #2980b9; }
        .controls input { padding: 8px; border: 1px solid #ddd; border-radius: 6px; width: 60px; }
        canvas { border: 1px solid #ddd; border-radius: 8px; }
        .info { margin-top: 10px; font-size: 14px; color: #666; }
    </style>
</head>
<body>
    <div class="container">
        <h1>📊 Слупковая дыяграма</h1>
        <div class="controls">
            <label>Назва катэгорыі:
                <input type="text" id="catName" value="Новая">
            </label>
            <label>Значэнне:
                <input type="number" id="catValue" value="50" min="1" max="100">
            </label>
            <button id="addBtn">+ Дадаць</button>
            <button id="clearBtn" style="background:#e74c3c;">Ачысціць</button>
        </div>
        <canvas id="canvas" width="700" height="400"></canvas>
        <div class="info">📌 Націсніце "Дадаць" для пабудовы дыяграмы</div>
    </div>

    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const catName = document.getElementById('catName');
        const catValue = document.getElementById('catValue');
        const addBtn = document.getElementById('addBtn');
        const clearBtn = document.getElementById('clearBtn');

        let data = [
            { label: 'А', value: 30 },
            { label: 'Б', value: 45 },
            { label: 'В', value: 60 },
            { label: 'Г', value: 25 },
            { label: 'Д', value: 80 }
        ];

        const colors = ['#3498db', '#2ecc71', '#e74c3c', '#f39c12', '#9b59b6', '#1abc9c', '#e67e22', '#34495e'];

        function drawChart() {
            const w = canvas.width;
            const h = canvas.height;
            const padding = { top: 40, bottom: 60, left: 50, right: 20 };
            const chartWidth = w - padding.left - padding.right;
            const chartHeight = h - padding.top - padding.bottom;

            ctx.clearRect(0, 0, w, h);

            // Фон
            ctx.fillStyle = '#f8f9fa';
            ctx.fillRect(0, 0, w, h);

            // Загаловак
            ctx.fillStyle = '#2c3e50';
            ctx.font = 'bold 20px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('Слупковая дыяграма', w/2, 28);

            if (data.length === 0) {
                ctx.fillStyle = '#999';
                ctx.font = '18px Arial';
                ctx.fillText('Няма даных для адлюстравання', w/2, h/2);
                return;
            }

            const maxValue = Math.max(...data.map(d => d.value), 10);
            const barWidth = Math.min(chartWidth / data.length * 0.7, 50);
            const spacing = chartWidth / data.length;

            // Сетка
            ctx.strokeStyle = '#e0e0e0';
            ctx.lineWidth = 0.5;
            for (let i = 0; i <= 5; i++) {
                const y = padding.top + chartHeight - (i / 5) * chartHeight;
                ctx.beginPath();
                ctx.moveTo(padding.left, y);
                ctx.lineTo(w - padding.right, y);
                ctx.stroke();
                ctx.fillStyle = '#666';
                ctx.font = '12px Arial';
                ctx.textAlign = 'right';
                ctx.fillText(Math.round((i / 5) * maxValue), padding.left - 10, y + 4);
            }

            // Слупкі
            for (let i = 0; i < data.length; i++) {
                const x = padding.left + i * spacing + (spacing - barWidth) / 2;
                const barHeight = (data[i].value / maxValue) * chartHeight;
                const y = padding.top + chartHeight - barHeight;

                ctx.fillStyle = colors[i % colors.length];
                ctx.fillRect(x, y, barWidth, barHeight);

                ctx.fillStyle = '#2c3e50';
                ctx.font = '12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(data[i].value, x + barWidth/2, y - 8);

                ctx.fillStyle = '#2c3e50';
                ctx.font = '12px Arial';
                ctx.fillText(data[i].label, x + barWidth/2, padding.top + chartHeight + 25);
            }
        }

        addBtn.addEventListener('click', function() {
            const name = catName.value.trim() || '?';
            const value = parseInt(catValue.value) || 1;
            data.push({ label: name, value: Math.min(Math.max(value, 1), 100) });
            drawChart();
            catName.value = '';
            catValue.value = '50';
        });

        clearBtn.addEventListener('click', function() {
            data = [];
            drawChart();
        });

        // Націсканне Enter у палях
        document.querySelectorAll('input').forEach(el => {
            el.addEventListener('keypress', function(e) {
                if (e.key === 'Enter') addBtn.click();
            });
        });

        drawChart();
    </script>
</body>
</html>
```

📌 **Chart.js — папулярная бібліятэка для дыяграм:**

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Chart.js</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body>
    <div style="max-width: 600px; margin: 40px auto;">
        <h2>📈 Графік з Chart.js</h2>
        <canvas id="myChart"></canvas>
        <button id="updateBtn" style="margin-top:10px; padding:10px 20px;">Абнавіць даныя</button>
    </div>

    <script>
        const ctx = document.getElementById('myChart').getContext('2d');

        const chart = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: ['Студзень', 'Люты', 'Сакавік', 'Красавік', 'Май'],
                datasets: [{
                    label: 'Продажы (тыс. руб.)',
                    data: [12, 19, 15, 22, 28],
                    backgroundColor: ['#3498db', '#2ecc71', '#e74c3c', '#f39c12', '#9b59b6']
                }]
            },
            options: {
                responsive: true,
                plugins: {
                    title: {
                        display: true,
                        text: 'Продажы па месяцах'
                    }
                }
            }
        });

        document.getElementById('updateBtn').addEventListener('click', function() {
            chart.data.datasets[0].data = [
                Math.random() * 30 + 5,
                Math.random() * 30 + 5,
                Math.random() * 30 + 5,
                Math.random() * 30 + 5,
                Math.random() * 30 + 5
            ];
            chart.update();
        });
    </script>
</body>
</html>
