    <script>
        const noteArea = document.getElementById('noteArea');
        const charCount = document.getElementById('charCount');
        const wordCount = document.getElementById('wordCount');
        const saveStatus = document.getElementById('saveStatus');
        const statusBar = document.getElementById('statusBar');

        function updateStats() {
            const text = noteArea.value;
            charCount.textContent = 'Сімвалаў: ' + text.length;
            const words = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;
            wordCount.textContent = 'Слоў: ' + words;
        }

        function setStatus(text, isSuccess = true) {
            statusBar.textContent = (isSuccess ? '✅ ' : '❌ ') + text;
            statusBar.style.color = isSuccess ? '#2ecc71' : '#e74c3c';
            setTimeout(() => {
                statusBar.style.color = '#666';
            }, 2000);
        }

        noteArea.addEventListener('input', function() {
            updateStats();
            saveStatus.textContent = '📌 Не захавана';
        });

        document.getElementById('newBtn').addEventListener('click', function() {
            if (noteArea.value.trim() !== '') {
                if (!confirm('Нататка не захавана. Працягнуць?')) return;
            }
            noteArea.value = '';
            updateStats();
            saveStatus.textContent = '📄 Новы дакумент';
            setStatus('Створана новая нататка');
        });

        document.getElementById('saveBtn').addEventListener('click', function() {
            const text = noteArea.value.trim();
            if (text === '') {
                setStatus('Няма чаго захоўваць!', false);
                return;
            }
            localStorage.setItem('note_' + Date.now(), text);
            saveStatus.textContent = '💾 Захавана (' + new Date().toLocaleTimeString() + ')';
            setStatus('Нататка захавана!');
        });

        document.getElementById('clearBtn').addEventListener('click', function() {
            if (noteArea.value.trim() !== '' && !confirm('Ачысціць нататку?')) return;
            noteArea.value = '';
            updateStats();
            saveStatus.textContent = '🗑️ Ачышчана';
            setStatus('Нататка ачышчана');
        });

        document.getElementById('countBtn').addEventListener('click', function() {
            const text = noteArea.value.trim();
            const words = text === '' ? 0 : text.split(/\s+/).length;
            const chars = text.length;
            const lines = text === '' ? 0 : text.split('\n').length;
            alert('📊 Статыстыка:\n' +
                  'Сімвалаў: ' + chars + '\n' +
                  'Слоў: ' + words + '\n' +
                  'Радкоў: ' + lines);
        });

        // Меню (для дэманстрацыі)
        document.getElementById('menuFile').addEventListener('click', function() {
            alert('📁 Меню "Файл"\nНовы - Ctrl+N\nЗахаваць - Ctrl+S');
        });
        document.getElementById('menuEdit').addEventListener('click', function() {
            alert('✏️ Меню "Праўка"\nВыразаць - Ctrl+X\nКапіраваць - Ctrl+C\nУставіць - Ctrl+V');
        });
        document.getElementById('menuHelp').addEventListener('click', function() {
            alert('❓ Даведка\nНататкі v1.0\nСтворана для ўрокаў інфарматыкі');
        });

        // Кнопкі акна (дэманстрацыя)
        document.querySelector('.close').addEventListener('click', function() {
            if (confirm('Закрыць прыкладанне?')) {
                document.querySelector('.window').style.opacity = '0';
                document.querySelector('.window').style.transition = '0.5s';
                setTimeout(() => {
                    document.querySelector('.window').style.display = 'none';
                }, 500);
            }
        });

        updateStats();
        setStatus('Прыкладанне запушчана!');
    </script>
</body>
</html>
