    <div class="app">
        <h1>📋 Спіс задач</h1>
        <div class="input-row">
            <input type="text" id="taskInput" placeholder="Новая задача..." maxlength="100">
            <button id="addBtn">Дадаць</button>
        </div>
        <div class="filters">
            <button class="active" data-filter="all">Усе</button>
            <button data-filter="active">Актыўныя</button>
            <button data-filter="completed">Выкананыя</button>
        </div>
        <ul class="task-list" id="taskList"></ul>
        <div class="stats">
            <span id="totalCount">Усяго: 0</span>
            <span id="activeCount">Актыўныя: 0</span>
            <span id="completedCount">Выкананыя: 0</span>
        </div>
    </div>

    <script>
        let tasks = [];
        let currentFilter = 'all';

        const taskList = document.getElementById('taskList');
        const taskInput = document.getElementById('taskInput');
        const addBtn = document.getElementById('addBtn');
        const totalCount = document.getElementById('totalCount');
        const activeCount = document.getElementById('activeCount');
        const completedCount = document.getElementById('completedCount');

        function loadTasks() {
            const saved = localStorage.getItem('tasks');
            if (saved) tasks = JSON.parse(saved);
        }

        function saveTasks() {
            localStorage.setItem('tasks', JSON.stringify(tasks));
        }

        function renderTasks() {
            let filtered = tasks;
            if (currentFilter === 'active') {
                filtered = tasks.filter(t => !t.completed);
            } else if (currentFilter === 'completed') {
                filtered = tasks.filter(t => t.completed);
            }

            if (filtered.length === 0) {
                taskList.innerHTML = '<div class="empty">💡 Няма задач</div>';
            } else {
                taskList.innerHTML = filtered.map((task, index) => {
                    const realIndex = tasks.indexOf(task);
                    return `
                        <li class="task-item ${task.completed ? 'completed' : ''}">
                            <input type="checkbox" class="checkbox" ${task.completed ? 'checked' : ''} data-index="${realIndex}">
                            <span class="task-text">${escapeHtml(task.text)}</span>
                            <span class="task-date">${task.date}</span>
                            <button class="delete-btn" data-index="${realIndex}">✕</button>
                        </li>
                    `;
                }).join('');
            }

            updateStats();
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function updateStats() {
            const total = tasks.length;
            const active = tasks.filter(t => !t.completed).length;
            const completed = tasks.filter(t => t.completed).length;
            totalCount.textContent = `Усяго: ${total}`;
            activeCount.textContent = `Актыўныя: ${active}`;
            completedCount.textContent = `Выкананыя: ${completed}`;
        }

        function addTask() {
            const text = taskInput.value.trim();
            if (text === '') {
                taskInput.style.borderColor = '#e74c3c';
                setTimeout(() => taskInput.style.borderColor = '#ddd', 1500);
                return;
            }

            const now = new Date();
            const dateStr = now.toLocaleDateString('be-BY') + ' ' + now.toLocaleTimeString('be-BY', {hour: '2-digit', minute:'2-digit'});

            tasks.push({
                id: Date.now(),
                text: text,
                completed: false,
                date: dateStr
            });

            saveTasks();
            renderTasks();
            taskInput.value = '';
            taskInput.focus();
        }

        function toggleTask(index) {
            tasks[index].completed = !tasks[index].completed;
            saveTasks();
            renderTasks();
        }

        function deleteTask(index) {
            if (confirm('Выдаліць задачу?')) {
                tasks.splice(index, 1);
                saveTasks();
                renderTasks();
            }
        }

        // Падзеі
        addBtn.addEventListener('click', addTask);

        taskInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') addTask();
        });

        taskList.addEventListener('click', function(e) {
            const target = e.target;
            if (target.classList.contains('checkbox')) {
                const index = parseInt(target.dataset.index);
                toggleTask(index);
            } else if (target.classList.contains('delete-btn')) {
                const index = parseInt(target.dataset.index);
                deleteTask(index);
            }
        });

        document.querySelectorAll('.filters button').forEach(btn => {
            btn.addEventListener('click', function() {
                document.querySelectorAll('.filters button').forEach(b => b.classList.remove('active'));
                this.classList.add('active');
                currentFilter = this.dataset.filter;
                renderTasks();
            });
        });

        loadTasks();
        renderTasks();
    </script>
</body>
</html>
