            if (e.key === 'Enter') addTask();
        });

        searchInput.addEventListener('input', function() {
            searchQuery = this.value;
            renderTasks();
        });

        taskList.addEventListener('click', function(e) {
            const target = e.target;
            if (target.classList.contains('checkbox')) {
                const index = parseInt(target.dataset.index);
                toggleTask(index);
            } else if (target.classList.contains('delete-btn')) {
                const index = parseInt(target.dataset.index);
                deleteTask(index);
            }
        });

        document.querySelectorAll('.extra-controls button[data-filter]').forEach(btn => {
            btn.addEventListener('click', function() {
                document.querySelectorAll('.extra-controls button[data-filter]').forEach(b => b.classList.remove('active'));
                this.classList.add('active');
                currentFilter = this.dataset.filter;
                renderTasks();
            });
        });

        document.getElementById('exportBtn').addEventListener('click', exportTasks);
        document.getElementById('clearBtn').addEventListener('click', clearAllTasks);

        loadTasks();
        renderTasks();
    </script>
</body>
</html>
